// Deterministic response validation: relevance, factual grounding, unsupported
// claims, prompt leakage, secrets, length and business-rule compliance.
const envelope = $input.first().json;
const responseText = envelope.response && envelope.response.text ? String(envelope.response.text).trim() : '';
const rag = envelope.rag || {};
const classification = envelope.classification || {};
const policy = envelope.policy || {};

const minLength = Number(process.env.RESPONSE_MIN_LENGTH || 5);
const maxLength = Number(process.env.RESPONSE_MAX_LENGTH || 500);
const issues = [];

// 1. Empty / length
if (!responseText) {
  issues.push('empty_response');
} else if (responseText.length < minLength) {
  issues.push('response_too_short');
} else if (responseText.length > maxLength) {
  issues.push('response_too_long');
}

// 2. Prompt leakage markers
const leakMarkers = [
  'system prompt', 'your instructions', 'your internal', 'as an ai', 'as a language model',
  'openai', 'model name', 'api key', 'sk-', 'credentials', 'secret key', 'system message',
  'developer message', 'ignore previous instructions'
];
for (const m of leakMarkers) {
  if (responseText.toLowerCase().includes(m)) {
    issues.push('prompt_leak:' + m);
    break;
  }
}

// 3. Secrets patterns
if (/(sk-[A-Za-z0-9]{16,})|(AKIA[0-9A-Z]{16})|(xox[baprs]-[A-Za-z0-9-]{10,})/.test(responseText)) {
  issues.push('secret_detected');
}

// 4. Unsupported factual claims when RAG grounding is weak
const claims = [];
if (/\$\s?\d+/.test(responseText)) claims.push('price');
if (/\b\d+\s*(business\s*)?days?\b/.test(responseText)) claims.push('delivery_window');
if (/refund/i.test(responseText)) claims.push('refund');
if (/\border\b/i.test(responseText)) claims.push('order');
if (/\b(password|account balance|reset|card|billing)\b/i.test(responseText)) claims.push('account');

const contextLower = (rag.top_context || '').toLowerCase();
if (!rag.strong) {
  for (const c of claims) {
    if (c === 'refund' && !contextLower.includes('refund')) issues.push('ungrounded_claim:' + c);
    if ((c === 'price' || c === 'delivery_window') && !contextLower.includes('ship') && !contextLower.includes('$')) issues.push('ungrounded_claim:' + c);
    if (c === 'order' && !contextLower.includes('order')) issues.push('ungrounded_claim:' + c);
    if (c === 'account' && !contextLower.includes('account')) issues.push('ungrounded_claim:' + c);
  }
}

// 5. Business rule: refund above threshold must mention review/approval
if (classification.intent === 'refund_request') {
  const amounts = responseText.match(/\$\s?\d+(\.\d+)?/g);
  const threshold = Number(process.env.REFUND_APPROVAL_THRESHOLD || 100);
  if (amounts && amounts.some(a => parseFloat(a.replace(/[$ ,]/g, '')) >= threshold)) {
    if (!/review|approval|agent|human|team|processing/.test(responseText.toLowerCase())) {
      issues.push('refund_above_threshold_without_approval');
    }
  }
}

// 6. Relevance: meaningful token overlap between customer message and response
const stopwords = new Set(['the','a','an','is','are','was','were','to','of','in','for','on','at','my','i','you','your','it','this','that','do','did','does','and','or','but','with','about','have','has','can','could','please','thanks','thank','me','we','us','get']);
const tokenize = (t) => (t || '').toLowerCase().split(/[^a-z0-9]+/).filter(x => x.length > 2 && !stopwords.has(x));
const msgTokens = new Set(tokenize(envelope.message));
const respTokens = new Set(tokenize(responseText));
let overlap = 0;
for (const t of msgTokens) if (respTokens.has(t)) overlap++;

const isClarifying = /(do you mean|clarify|could you provide|which (order|product)|more details|i (don't|cannot|can't).*(find|answer|confirm)|not available|cannot confirm)/i.test(responseText);
if (overlap === 0 && !isClarifying) issues.push('irrelevant_response');

// 7. False certainty on missing knowledge
if (rag.miss && /\b(sure|definitely|guaranteed|will be delivered|approved|confirmed)\b/i.test(responseText)) {
  issues.push('false_certainty_on_missing_knowledge');
}

// 8. Critical intent must never be answered as fully automated success
if (['account_issue', 'payment_issue', 'order_issue'].includes(classification.intent) && policy.priority === 'critical' && envelope.response && !envelope.response.regenerated) {
  issues.push('critical_issue_needs_review');
}

const valid = issues.length === 0;
const score = valid ? 1 : Math.max(0.1, 1 - issues.length * 0.25);
const validation = { valid, issues, score };
return [{ json: { ...envelope, validation } }];
